const e={educacao:{titulo:"Educação para Todos",categoria:"Educação",descricao:"Projeto voltado ao apoio educacional de crianças e adolescentes em situação de vulnerabilidade social, oferecendo atividades de reforço escolar, leitura e desenvolvimento pessoal."},alimento:{titulo:"Alimento Solidário",categoria:"Alimentação",descricao:"Campanha destinada à arrecadação e distribuição de alimentos para famílias que enfrentam dificuldades financeiras e insegurança alimentar."},inclusao:{titulo:"Inclusão e Oportunidades",categoria:"Inclusão",descricao:"Iniciativa que busca promover inclusão social e ampliar oportunidades por meio de oficinas, capacitação e orientação para pessoas em situação de vulnerabilidade."}};export function initProjects(){const o=document.querySelector("#project-modal");if(!o)return;const a=document.querySelectorAll(".project-modal-button"),t=document.querySelector("#modal-title"),i=document.querySelector("#modal-badge"),c=document.querySelector("#modal-description"),r=o.querySelector(".modal-close");a.forEach(a=>{a.addEventListener("click",()=>{const r=a.dataset.project,d=e[r];d&&(t.textContent=d.titulo,i.textContent=d.categoria,c.textContent=d.descricao,o.showModal())})}),r.addEventListener("click",()=>{o.close()}),o.addEventListener("click",e=>{e.target===o&&o.close()})}